    word_length = len(word)

    # Ignore vowels at the beginning and end
    start, end = 0, word_length - 1
    while start < word_length and word[start] in vowels:
        start += 1
    while end >= 0 and word[end] in vowels:
        end -= 1

    # Find the last consonant and the closest vowel to its right
    for i in range(end, start - 1, -1):
        if word[i] not in vowels:
            for j in range(i + 1, end + 1):
                if word[j] in vowels:
                    return word[j]
            break

    return ""
